            Absolute::Follow => self
                .file
                .absolute_path()
                .and_then(|p| p.to_str())
                .map(std::borrow::ToOwned::to_owned),
            Absolute::Off => None,
        }
        .unwrap_or(self.file.name.clone())
    }

